            scale, word_value = self.numwords.get(word, (0, 0))

            if scale == 100:
                last_group = (last_group * 0 + word_value) * 100
            else:
                last_group = last_group + word_value

            return (last_group, 0)

        return last_group

    words = [w for w in words if w not in self.numwords and w != "and"]

    result = 0
